import { useEffect, useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  Link,
  useNavigate,
} from "react-router-dom";
import axios from "axios";

import sorsuLogo from "./assets/sorsu-logo.png";

import AdminPanel from "./components/AdminPanel";
import AdminCodesPanel from "./components/AdminCodesPanel";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import AuthPage from "./components/AuthPage";
import VoterDashboard from "./components/VoterDashboard";
import CandidatesPage from "./components/CandidatesPage";
import AdminFeedback from "./pages/AdminFeedback";
import BallotReceiptPage from "./components/BallotReceiptPage";

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");
  const [hasVoted, setHasVoted] = useState(false);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token"),
    role: localStorage.getItem("role"),
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    partylist: "",
    yearLevel: "",
    block: "",
    course: "",
    description: "",
    image: null,
  });

  const theme = {
    background: "#f1f5f9",
    navbar: "#ffffff",
    card: "#ffffff",
    text: "#0f172a",
    button: "#6366f1",
  };

  // =========================
  // FETCH CANDIDATES
  // =========================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 10000);
    return () => clearInterval(interval);
  }, []);

  // =========================
  // CHECK USER VOTES
  // =========================
  useEffect(() => {
    const fetchMyVotes = async () => {
      if (!auth.token) return;

      try {
        const res = await axios.get(`${API_URL}/api/vote/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setHasVoted(res.data.length > 0);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMyVotes();
  }, [auth.token]);

  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // =========================
  // SAVE CANDIDATE
  // =========================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      Object.keys(candidateForm).forEach((key) => {
        if (candidateForm[key]) formData.append(key, candidateForm[key]);
      });

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: {
            Authorization: `Bearer ${auth.token}`,
            "Content-Type": "multipart/form-data",
          },
        });
        setMessage("Candidate updated successfully.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: {
            Authorization: `Bearer ${auth.token}`,
            "Content-Type": "multipart/form-data",
          },
        });
        setMessage("Candidate added successfully.");
      }

      setEditId(null);
      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        partylist: "",
        yearLevel: "",
        block: "",
        course: "",
        description: "",
        image: null,
      });

      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch (err) {
      console.error(err);
      setMessage("Failed to save candidate.");
    }
  };

  // =========================
  // DELETE CANDIDATE
  // =========================
  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });

      setMessage("Candidate deleted.");
      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch {
      setMessage("Delete failed.");
    }
  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  return (
    <Router>
      {/* =========================
          AUTH (NOT LOGGED IN)
      ========================= */}
      {!auth.token && (
        <Routes>
          <Route path="*" element={<AuthPage setAuth={setAuth} />} />
        </Routes>
      )}

      {/* =========================
          VOTER ROUTES ONLY
      ========================= */}
      {auth.token && auth.role !== "admin" && (
        <Routes>
          <Route path="/dashboard" element={<VoterDashboard auth={auth} electionClosed={electionClosed} />} />
          <Route path="/candidates" element={<CandidatesPage auth={auth} />} />
          <Route path="/my-votes" element={<BallotReceiptPage auth={auth} />} />
          <Route path="*" element={<Navigate to="/dashboard" />} />
        </Routes>
      )}

      {/* =========================
          ADMIN ROUTES ONLY
      ========================= */}
      {auth.token && auth.role === "admin" && (
        <AdminApp
          auth={auth}
          theme={theme}
          candidates={candidates}
          candidateForm={candidateForm}
          setCandidateForm={setCandidateForm}
          editId={editId}
          setEditId={setEditId}
          handleSaveCandidate={handleSaveCandidate}
          handleDeleteCandidate={handleDeleteCandidate}
          showAnonymous={showAnonymous}
          setShowAnonymous={setShowAnonymous}
          electionClosed={electionClosed}
          setElectionClosed={setElectionClosed}
          hasVoted={hasVoted}
          message={message}
          totalVotes={totalVotes}
          handleLogout={handleLogout}
        />
      )}
    </Router>
  );
}

// =========================
// ADMIN APP
// =========================
function AdminApp({
  auth,
  theme,
  candidates,
  candidateForm,
  setCandidateForm,
  editId,
  setEditId,
  handleSaveCandidate,
  handleDeleteCandidate,
  showAnonymous,
  setShowAnonymous,
  electionClosed,
  setElectionClosed,
  hasVoted,
  message,
  totalVotes,
  handleLogout,
}) {
  const navigate = useNavigate();

  const handleCloseElection = async () => {
    try {
      await axios.put(`${API_URL}/api/election/close`, null, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });

      setElectionClosed(true);

      // ✅ GO TO RESULTS
      navigate("/admin/results");
    } catch (err) {
      console.error(err);
      alert("Failed to close election");
    }
  };

  const handleOpenElection = async () => {
    try {
      await axios.put(`${API_URL}/api/election/open`, null, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });

      setElectionClosed(false);
    } catch (err) {
      console.error(err);
      alert("Failed to open election");
    }
  };

  return (
    <div style={{ minHeight: "100vh", backgroundColor: theme.background }}>
      <div style={navbarStyle(theme)}>
        <div style={{ display: "flex", gap: 12 }}>
          <img src={sorsuLogo} alt="logo" style={{ height: 50 }} />
          <h2>SorSU Voting Admin</h2>
        </div>

        <div style={{ display: "flex", gap: 10 }}>
          <button
            onClick={electionClosed ? handleOpenElection : handleCloseElection}
            style={{
              ...modernButton(theme),
              backgroundColor: electionClosed ? "#10b981" : "#ef4444",
            }}
          >
            {electionClosed ? "Open Election" : "Close Election"}
          </button>

          <button onClick={handleLogout} style={{ ...modernButton(theme), backgroundColor: "#ef4444" }}>
            Logout
          </button>
        </div>
      </div>

      <div style={{ padding: 20 }}>
        <h2>Admin Panel</h2>

        {message && <p>{message}</p>}

        <div>Total Votes: {totalVotes}</div>

        <AdminPanel
          candidateForm={candidateForm}
          setCandidateForm={setCandidateForm}
          onSave={handleSaveCandidate}
          editId={editId}
          setEditId={setEditId}
          onDelete={handleDeleteCandidate}
          candidates={candidates}
          theme={theme}
        />

        <AdminCodesPanel />

        {showAnonymous && <AdminAnonymousResults theme={theme} />}
      </div>
    </div>
  );
}

// =========================
// STYLES
// =========================
const modernButton = (theme) => ({
  padding: "8px 14px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
});

const navbarStyle = (theme) => ({
  display: "flex",
  justifyContent: "space-between",
  padding: "15px",
  background: theme.navbar,
});

export default App;
